<?php
declare(strict_types=1);
$isHttps=isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!==''&&$_SERVER['HTTPS']!=='off';ini_set('session.use_strict_mode','1');session_name('coaching_tool_session');session_set_cookie_params(['httponly'=>true,'secure'=>$isHttps,'samesite'=>'Strict','path'=>'/']);session_start();header('Cache-Control: no-store, private');
require_once dirname(__DIR__).'/app/bootstrap.php';require_once dirname(__DIR__).'/app/navigation.php';
function mfaResetH(string|int|null $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$user=$_SESSION['user']??null;if(!is_array($user)||($user['role']??'')!=='admin'){http_response_code(403);exit('Nur Administratoren können MFA für Benutzer zurücksetzen.');}
$db=coachingDatabase();$token=$_SESSION['csrf_token']??'';if(!is_string($token)||strlen($token)!==64){$token=bin2hex(random_bytes(32));$_SESSION['csrf_token']=$token;}$error='';$notice=isset($_GET['reset'])?'Die Zwei-Faktor-Anmeldung wurde zurückgesetzt. Der Benutzer muss sie nach dem nächsten Passwort-Login neu einrichten.':'';
if($_SERVER['REQUEST_METHOD']==='POST'){$posted=$_POST['csrf_token']??'';$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$id=$id===false?0:(int)$id;if(!is_string($posted)||!hash_equals($token,$posted))$error='Die Anfrage ist abgelaufen. Bitte lade die Seite neu.';elseif($id<1||$id===(int)$user['id'])$error='Wähle ein anderes Benutzerkonto. Das eigene Konto kann hier nicht zurückgesetzt werden.';else try{$db->beginTransaction();$q=$db->prepare("SELECT id,rolle FROM benutzer WHERE id=:id AND rolle IN ('admin','verwalter','coach') FOR UPDATE");$q->execute(['id'=>$id]);$target=$q->fetch(PDO::FETCH_ASSOC);if(!$target)throw new InvalidArgumentException('Das Benutzerkonto wurde nicht gefunden.');$save=$db->prepare('UPDATE benutzer SET mfa_aktiv=0,mfa_geheimnis_verschluesselt=NULL,mfa_ersatzcodes_hashes=NULL WHERE id=:id');$save->execute(['id'=>$id]);$audit=$db->prepare("INSERT INTO coaching_admin_aktionen (admin_benutzer_id,aktion,ziel_typ,ziel_id) VALUES (:admin,'mfa_zurueckgesetzt','benutzer',:target)");$audit->execute(['admin'=>(int)$user['id'],'target'=>$id]);$db->commit();header('Location: mfa-reset.php?reset=1');exit;}catch(InvalidArgumentException $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Coaching Tool MFA reset failed: '.$e->getMessage());$error='Die MFA-Anmeldung konnte nicht zurückgesetzt werden. Prüfe Migration 022 und Tabellenrechte.';}}
$accounts=$db->query("SELECT id,vorname,nachname,benutzername,rolle,aktiv,mfa_aktiv FROM benutzer WHERE rolle IN ('admin','verwalter','coach') ORDER BY rolle,nachname,vorname")->fetchAll(PDO::FETCH_ASSOC);$csrf=$token;
?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Zwei-Faktor-Zugänge verwalten · Coaching Tool</title><link rel="stylesheet" href="assets/layout.css"><script src="assets/layout.js" defer></script><style>.page{max-width:1000px;margin:auto;padding:32px clamp(20px,4vw,56px) 64px}.card{background:#fff;border:1px solid #e3ebe5;border-radius:14px;padding:20px;margin:18px 0}.row{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:13px 0;border-bottom:1px solid #edf1ee}.button{border:0;border-radius:8px;padding:9px 12px;background:#245c50;color:white;font:inherit;cursor:pointer}.danger{background:#8a3f38}.muted{color:#718078;font-size:13px}.notice,.error{padding:12px;border-radius:8px}.notice{background:#edf5ef}.error{background:#fff3f1;color:#842f2f}@media(max-width:700px){.row{align-items:flex-start;flex-direction:column}}</style></head><body class="has-app-sidebar"><?php renderCoachingSidebar($user,'mfa-reset',$csrf);?><main class="page"><h1>Zwei-Faktor-Zugänge</h1><p>Hier kann ein Administrator die MFA eines Coaches, Verwalters oder eines anderen Administrators zurücksetzen. Der nächste Login verlangt eine neue Einrichtung. Das eigene Konto kann nicht zurückgesetzt werden.</p><?php if($notice):?><p class="notice" role="status"><?=mfaResetH($notice)?></p><?php endif;?><?php if($error):?><p class="error" role="alert"><?=mfaResetH($error)?></p><?php endif;?><section class="card"><?php foreach($accounts as $account):?><div class="row"><div><strong><?=mfaResetH($account['vorname'].' '.$account['nachname'])?></strong><div class="muted"><?=mfaResetH($account['rolle'])?> · <?=mfaResetH($account['benutzername'])?> · <?=((int)$account['aktiv']===1?'Aktiv':'Inaktiv')?> · MFA <?=((int)$account['mfa_aktiv']===1?'aktiv':'noch nicht eingerichtet')?></div></div><?php if((int)$account['id']!==(int)$user['id']):?><form method="post" onsubmit="return confirm('MFA dieses Kontos wirklich zurücksetzen? Der Benutzer muss sie beim nächsten Login neu einrichten.');"><input type="hidden" name="csrf_token" value="<?=mfaResetH($csrf)?>"><input type="hidden" name="id" value="<?=(int)$account['id']?>"><button class="button danger" type="submit">MFA zurücksetzen</button></form><?php else:?><span class="muted">Eigenes Konto</span><?php endif;?></div><?php endforeach;?></section></main></body></html>